#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_equals_equal_buffers(void) {
    // Setup: create two buffers with identical null-terminated string data
    const char *test_str = "Hello, World!";
    buffer_t *buf1 = buffer_new_with_copy(test_str);
    buffer_t *buf2 = buffer_new_with_copy(test_str);

    TEST_ASSERT_NOT_NULL(buf1);
    TEST_ASSERT_NOT_NULL(buf2);

    // Test: compare the two buffers
    int result = buffer_equals(buf1, buf2);

    // Assertions: should be equal
    TEST_ASSERT_EQUAL_INT(1, result);

    // Cleanup
    buffer_free(buf1);
    buffer_free(buf2);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_equals_equal_buffers);
    return UNITY_END();
}

